// =====================================================================
// 特売の食材（チラシの読み取り結果や、手でのチェックに使う一覧）
// ---------------------------------------------------------------------
//   id           : 区別するための英字の名前（重複しないように）
//   label        : 画面に出す名前
//   group        : 画面で分ける見出し
//   match        : レシピの材料名にこの言葉が含まれていれば「その食材を使う」とみなす
//   exclude      : （任意）この言葉が含まれる材料は対象外にする
//   flyer        : チラシの読み取り結果にこの言葉があれば「特売の食材が見つかった」とみなす
//                  （チラシでは「玉葱」「人参」「どりモモ」のような書き方も多いため、別に用意する）
//   flyerExclude : （任意）チラシの読み取り結果からこの言葉を取り除いてから探す
//                  （例：「ねぎ」を探す前に「玉ねぎ」を取り除く）
// 例：「豚肉」は "豚" で、豚こま切れ肉・豚バラ薄切り肉・豚ひき肉 などに当てはまる
// =====================================================================

